changes.sections/image-with-text-split.liquid:
{% # theme-check-disable %}
<div class="image-with-text image-with-text--{{ section.settings.image_position }} image-with-text--{{ section.settings.image_width }}" style="padding-top: {{ section.settings.padding_top }}px;">
  <div class="image-with-text__media">
    {%- if section.settings.image != blank -%}
      {{ section.settings.image | image_url: width: 1200 | image_tag: loading: 'lazy' }}
    {%- else -%}
      {{ 'image' | placeholder_svg_tag: 'image-with-text__placeholder' }}
    {%- endif -%}
  </div>
  <div class="image-with-text__content">
    {%- if section.settings.heading != blank -%}
      <h2>{{ section.settings.heading | escape }}</h2>
    {%- endif -%}
    {%- if section.settings.text != blank -%}
      <div class="image-with-text__text">{{ section.settings.text }}</div>
    {%- endif -%}
    {%- if section.settings.button_label != blank -%}
      {%- if section.settings.button_link != blank -%}
        <a class="button" href="{{ section.settings.button_link }}">{{ section.settings.button_label | escape }}</a>
      {%- else -%}
        <span class="button button--disabled">{{ section.settings.button_label | escape }}</span>
      {%- endif -%}
    {%- endif -%}
  </div>
</div>

{% schema %}
{"name":"Image with text","tag":"section","class":"section-image-with-text","settings":[{"type":"image_picker","id":"image","label":"Image"},{"type":"select","id":"image_position","label":"Image position","options":[{"value":"left","label":"Left"},{"value":"right","label":"Right"}],"default":"left"},{"type":"select","id":"image_width","label":"Image width","options":[{"value":"small","label":"Small"},{"value":"medium","label":"Medium"},{"value":"large","label":"Large"}],"default":"medium"},{"type":"header","content":"Content"},{"type":"text","id":"heading","label":"Heading","default":"Image with text"},{"type":"richtext","id":"text","label":"Text","default":"<p>Pair text with an image to tell your brand story.</p>"},{"type":"text","id":"button_label","label":"Button label"},{"type":"url","id":"button_link","label":"Button link"},{"type":"range","id":"padding_top","label":"Top padding","min":0,"max":80,"step":4,"unit":"px","default":36}],"presets":[{"name":"Image with text"}]}
{% endschema %}
